  "client/core/Kniu-Ui/Kniu-StatusComponent/Kniu-StatusComponent.css": ":host {\n  --kniu-status-color: var(--kniu-color-primary, #409eff);\n  display: inline-flex;\n  vertical-align: middle\n}\n\n:host([type=\"success\"]) {\n  --kniu-status-color: var(--kniu-color-success, #67c23a)\n}\n\n:host([type=\"warning\"]) {\n  --kniu-status-color: var(--kniu-color-warning, #e6a23c)\n}\n\n:host([type=\"danger\"]) {\n  --kniu-status-color: var(--kniu-color-danger, #f56c6c)\n}\n\n:host([type=\"info\"]) {\n  --kniu-status-color: var(--kniu-color-info, #909399)\n}\n\n.kniu_sys_status {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  color: var(--kniu-text-color, #606266);\n  font: 14px/1.5 var(--kniu-font-family);\n  white-space: nowrap\n}\n\n.kniu_sys_status_dot {\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background-color: var(--kniu-status-color);\n  flex: none\n}\n\n:host([size=\"large\"]) .kniu_sys_status {\n  font-size: 16px\n}\n\n:host([size=\"large\"]) .kniu_sys_status_dot {\n  width: 8px;\n  height: 8px\n}\n\n:host([size=\"small\"]) .kniu_sys_status {\n  gap: 5px;\n  font-size: 12px\n}\n\n:host([size=\"small\"]) .kniu_sys_status_dot {\n  width: 5px;\n  height: 5px\n}",
