  "client/core/Kniu-Ui/Kniu-TabComponent/Kniu-TabComponent.css": ":host {\r\n  display: block;\r\n}\r\n\r\n:host([hidden])[hidden] {\r\n  display: none;\r\n}\r\n\r\n::slotted(kniu-tab-panel) {\r\n  display: block;\r\n}\r\n\r\n::slotted(kniu-tab-panel[hidden][hidden]) {\r\n  display: none;\r\n}\r\n\r\n.kniu_sys_tab {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  background-color: var(--kniu-fill-color, #f5f7fa);\r\n  border-radius: 8px;\r\n  padding: 4px;\r\n}\r\n\r\n.kniu_sys_tab_item {\r\n  appearance: none;\r\n  border: 0;\r\n  background-color: transparent;\r\n  color: var(--kniu-text-color, #606266);\r\n  font-size: 14px;\r\n  line-height: 22px;\r\n  padding: 6px 18px;\r\n  border-radius: 6px;\r\n  white-space: nowrap;\r\n  font-family: inherit;\r\n  cursor: pointer;\r\n  transition: background-color .2s, color .2s, box-shadow .2s;\r\n  -webkit-transition: background-color .2s, color .2s, box-shadow .2s;\r\n  -moz-transition: background-color .2s, color .2s, box-shadow .2s;\r\n  -ms-transition: background-color .2s, color .2s, box-shadow .2s;\r\n  -o-transition: background-color .2s, color .2s, box-shadow .2s;\r\n}\r\n\r\n.kniu_sys_tab_item:hover {\r\n  color: var(--kniu-color-primary, #409eff);\r\n}\r\n\r\n.kniu_sys_tab_item[data-active=\"true\"] {\r\n  background-color: #fff;\r\n  color: var(--kniu-color-primary, #409eff);\r\n  font-weight: 600;\r\n  box-shadow: 0 1px 4px rgba(0, 0, 0, .12);\r\n  -webkit-box-shadow: 0 1px 4px rgba(0, 0, 0, .12);\r\n  -moz-box-shadow: 0 1px 4px rgba(0, 0, 0, .12);\r\n  -ms-box-shadow: 0 1px 4px rgba(0, 0, 0, .12);\r\n  -o-box-shadow: 0 1px 4px rgba(0, 0, 0, .12);\r\n}\r\n\r\n.kniu_sys_tab_item:focus-visible {\r\n  outline: 2px solid var(--kniu-color-primary, #409eff);\r\n  outline-offset: 1px;\r\n}\r\n\r\n.kniu_sys_tab_item[data-active=\"true\"]:focus-visible {\r\n  outline-offset: -2px;\r\n}",
